import React from 'react';

export default function OCR() {
  return (
    <div>
      <h1 className="page-title bengali">OCR (পাঠ পড়া)</h1>
      <p className="page-subtitle bengali">এই পেজে OCR ইমপ্লিমেন্টেশন যোগ করা হবে — বর্তমানে প্লেসহোল্ডার।</p>
    </div>
  );
}
